-#include <jvmti.h>
-#include <cstring>
-
-static jvmtiEnv* jvmti = nullptr;
-
-jint JNICALL heap_ref_callback(jvmtiHeapReferenceKind reference_kind,
-                               const jvmtiHeapReferenceInfo* reference_info,
-                               jlong class_tag,
-                               jlong referrer_class_tag,
-                               jlong size,
-                               jlong* tag_ptr,
-                               jlong* referrer_tag_ptr,
-                               jint length,
-                               void* user_data) {
-    return JVMTI_VISIT_OBJECTS;
-}
-
-extern "C" JNIEXPORT jint JNICALL Java_FollowRefPrimTest_runTest(JNIEnv* env, jclass cls, jclass testClass) {
-    jvmtiHeapCallbacks heapCallBacks;
-    memset(&heapCallBacks, 0, sizeof(heapCallBacks));
-    heapCallBacks.heap_reference_callback = heap_ref_callback;
-
-    return jvmti->FollowReferences(0, testClass, nullptr, &heapCallBacks, nullptr);
-}
-
-extern "C" JNIEXPORT jint JNICALL Agent_OnLoad(JavaVM* vm, char* options, void* reserved) {
-    if (vm->GetEnv(reinterpret_cast<void**>(&jvmti), JVMTI_VERSION) != JNI_OK || !jvmti) {
-        return JNI_ERR;
-    }
-    jvmtiCapabilities capabilities;
-    memset(&capabilities, 0, sizeof(capabilities));
-    capabilities.can_tag_objects = 1;
-    if (jvmti->AddCapabilities(&capabilities) != JVMTI_ERROR_NONE) {
-        return JNI_ERR;
-    }
-    return JNI_OK;
-}
